  "activity.counted.title": "Що враховується",
  "activity.counted.methodWindows": "Кожен ввід оператора відкриває вікно на {window} хв, і вікна, що перекриваються, обʼєднуються. Кожна хвилина рахується один раз — для проєкту останнього вводу перед нею.",
  "activity.counted.methodEpisodes": "Кожен ввід оператора відкриває вікно на {window} хв. Вводи з проміжком не більше {break} хв складають один епізод, і враховується весь епізод разом із роботою агентів, за якою ви в ньому стежили. Кожна хвилина рахується один раз — для проєкту останнього вводу перед нею.",
  "activity.counted.halfHour": "Години у звіті округлюють день кожного проєкту, порахований лише з його власних повідомлень, до найближчих пів години, і будь-який ненульовий час — щонайменше пів години. Загальна сума округлює так само весь ваш час разом.",
  "activity.counted.parallel": "Проєкти, над якими ви працюєте паралельно, рахуються кожен окремо, тож сума годин проєктів зазвичай більша за загальну.",
  "activity.counted.clockHour": "Години у звіті зважують кожну годину за годинником: менше 10 покритих хвилин — нуль, від 10 до 39 — пів години, 40 і більше — година. Проєкт рахує лише хвилини власних повідомлень, а загальна сума — вікна всіх проєктів разом.",
  "activity.counted.operatorOnly": "Враховується лише справжній ввід оператора: повідомлення, яке Delegatus позначив як операторське, або набране людиною в терміналі агента. Каркаси запуску й ролей, шаблони етапів, перші повідомлення сесій, яких немає в реєстрі, сповіщення, власні повідомлення Delegatus після перезапуску, вставлені підказки, прикріплені знімки екрана й повідомлення від одного агента іншому виключено, як і все непозначене; кожен хост показує, скільки виключив і з якої причини.",
  "activity.counted.agent": "Час агентів (≈) наближений: кожен хід триває від повідомлення до останньої відповіді агента за часовими мітками повідомлень на цьому хості. Робота агентів поза вашим часом — без нагляду, і до вашого часу вона нічого не додає.",
  "activity.counted.hosts": "Ваш ввід читається з кожного очікуваного хоста. Хост, який не прочитано, робить свій проміжок невідомим, а підсумок без нього — нижня межа. Журнал запитів цього хоста записує лише запити через Delegatus, тож цей хост вважається прочитаним лише там, де його покриває експорт транскриптів.",
  "activity.counted.indexUpdated": "Час агентів востаннє проіндексовано {when}.",
  "activity.counted.gaps": "Транскрипти, яких немає в індексі (сесії OpenClaw, видалені транскрипти), не враховуються.",
