  "activity.drawer.m1": "Кожен ваш ввід відкриває вікно на {window} хвилин; вікна, що перетинаються, зливаються. Хвилина рахується один раз — для проєкту останнього вводу.",
  "activity.drawer.m1Episodes": "Кожен ваш ввід відкриває вікно на {window} хвилин, а вводи з проміжком до {break} хвилин складають один епізод. Хвилина рахується один раз — для проєкту останнього вводу.",
  "activity.drawer.m2": "Години у звіті зважують кожну годину за годинником: менше 10 хвилин — 0, 10–39 — пів години, 40 і більше — година. Кожен проєкт рахується окремо, тож сума проєктів зазвичай більша за загальну.",
