  "activity.drawer.m3": "Рахується лише ваш власний ввід. Промпти етапів, повідомлення між агентами, сповіщення та вставлений текст не враховуються.",
  "activity.drawer.m4": "Час агентів (≈) триває від повідомлення до останньої відповіді агента. У межах вашого часу на тому ж проєкті це нагляд; де хост цього проєкту не прочитано або дню ймовірно бракує джерела — неясно; решта — без нагляду, зокрема поки ви працювали над іншим проєктом. Ваш час і час агентів ніколи не додаються.",
